<?php declare(strict_types=1); ?>
<div class="mod-wrap"><ul><?php foreach ($boards as $b): ?><li><a href="<?= $v->url('mod.php?view=boards&id=' . $b['id']) ?>">/<?= $v::e($b['slug']) ?>/ — <?= $v::e($b['title']) ?></a></li><?php endforeach ?></ul><p><a href="<?= $v->url('mod.php?view=boards') ?>">Create a board</a></p>
<form action="<?= $v->url('mod.php') ?>" method="post"><?= $v->csrf() ?><input type="hidden" name="id" value="<?= $v::e($edit['id'] ?? 0) ?>"><input type="hidden" name="action" value="board-save"><fieldset><legend><?= $edit === null ? 'Create board' : 'Edit /' . $v::e($edit['slug']) . '/' ?></legend><?php if ($edit === null): ?><label>Board name <input name="slug" pattern="[a-z][a-z0-9_]{0,23}" maxlength="24" required></label><?php endif ?><label>Title <input name="title" maxlength="100" value="<?= $v::e($edit['title'] ?? '') ?>" required></label><label>Subtitle <input name="subtitle" maxlength="300" value="<?= $v::e($edit['subtitle'] ?? '') ?>"></label><label><input name="locked" type="checkbox" value="1" <?= ($edit['locked'] ?? 0) ? 'checked' : '' ?>> Read-only board</label><button>Save board</button></fieldset></form>
<?php if ($edit !== null): ?><form action="<?= $v->url('mod.php') ?>" method="post"><?= $v->csrf() ?><input type="hidden" name="id" value="<?= $v::e($edit['id']) ?>"><input type="hidden" name="action" value="board-delete"><fieldset><legend>Delete board</legend><p>This removes every thread, reply and attachment on this board.</p><label>Type <?= $v::e($edit['slug']) ?> to confirm <input name="confirm" required maxlength="24"></label><label>Your current password <input name="current_password" type="password" autocomplete="current-password" required maxlength="128"></label><button>Delete board</button></fieldset></form><?php endif ?></div>
